/* ==========================================================================
   Theoriemeesters.nl — site.css
   Tokens volgen het Theoriemeesters design system (navy, sky, yellow,
   Montserrat, 4px-grid, radius 4/6/8). Responsive via container queries op
   .site, zodat iedere pagina zich aanpast aan de breedte waarop ze getoond wordt.
   ========================================================================== */

.site {
  --navy: #0b2545;
  --navy-2: #163a66;
  --sky: #54a3d8;
  --sky-light: #81bbe1;
  --yellow: #ffcc00;
  --yellow-hover: #ffd633;
  --white: #ffffff;
  --page: #f4f7fa;
  --panel: #e8eef4;
  --border: #dedede;
  --control: #7b8794;
  --text: var(--navy);
  --muted: #5a6572;
  --inverse: #ffffff;
  --error: #b42318;
  --font-sans: Montserrat, system-ui, sans-serif;
  --r-sm: 4px;
  --r-md: 6px;
  --r-lg: 8px;
  --btn: 36px;
  --btn-lg: 48px;
  container: site / inline-size;
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  width: 100%;
}
.shell {
  --gutter: 40px;
  --section: 88px;
  --h-display: 44px;
  --h1: 38px;
  --h2: 30px;
  --h3: 22px;
  min-height: 100%;
  display: flex;
  flex-direction: column;
  position: relative;
}
.shell > main { flex: 1 0 auto; }
:where(.site) *, :where(.site) *::before, :where(.site) *::after { box-sizing: border-box; }
:where(.site) h1, :where(.site) h2, :where(.site) h3, :where(.site) h4, :where(.site) p, :where(.site) ul, :where(.site) ol, :where(.site) figure, :where(.site) blockquote, :where(.site) dl, :where(.site) dd, :where(.site) fieldset { margin: 0; }
:where(.site) ul, :where(.site) ol { padding: 0; list-style: none; }
:where(.site) fieldset { border: 0; padding: 0; min-width: 0; }
:where(.site) legend { padding: 0; }
:where(.site) a { color: inherit; text-decoration: none; }
:where(.site) svg { display: block; }
:where(.site) button, :where(.site) input, :where(.site) select, :where(.site) textarea { font: inherit; color: inherit; }
:where(.site) button { background: none; border: 0; padding: 0; cursor: pointer; }
:where(.site) :focus-visible { outline: 2px solid var(--navy); outline-offset: 2px; }
:where(.site) strong, :where(.site) b { font-weight: 700; }

.sr-only { position: absolute !important; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.skip-link { position: absolute; left: 16px; top: -60px; z-index: 100; background: var(--navy); color: #fff; padding: 10px 16px; border-radius: var(--r-md); font-weight: 700; }
.skip-link:focus { top: 12px; }

/* ---------- Layout ---------- */
.wrap { width: 100%; max-width: calc(1600px + 2 * var(--gutter)); margin-inline: auto; padding-inline: var(--gutter); }
.section { padding-block: var(--section); }
.section-tight-top { padding-top: 32px; padding-bottom: var(--section); }
.section-page { background: var(--page); }
.section-panel { background: var(--panel); }
.section-navy { background: var(--navy); color: var(--inverse); }
.section-navy .t-h2 { color: #fff; }
.section-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; margin-bottom: 40px; }
.section-head p { max-width: 640px; margin-top: 12px; }
.section-head-center { justify-content: center; text-align: center; }
.section-head-center p { margin-inline: auto; }

/* ---------- Typography ---------- */
.t-display { font-size: var(--h-display); line-height: 1.12; font-weight: 700; color: var(--navy); letter-spacing: 0; text-wrap: balance; }
.t-h1 { font-size: var(--h1); line-height: 1.2; font-weight: 700; color: var(--navy); text-wrap: balance; }
.t-h2 { font-size: var(--h2); line-height: 1.25; font-weight: 700; color: var(--navy); text-wrap: balance; }
.t-h3 { font-size: var(--h3); line-height: 1.3; font-weight: 600; color: var(--navy); }
.t-sm { font-size: 14px; line-height: 1.5; }
.t-cap { font-size: 12px; line-height: 1.4; }
.muted { color: var(--muted); }
.lead { font-size: 18px; line-height: 1.6; color: var(--muted); max-width: 620px; }
.lead-inv { color: rgba(255, 255, 255, .84); }
.inv-muted { color: rgba(255, 255, 255, .78); }
.eyebrow { display: inline-flex; align-items: center; gap: 10px; font-size: 14px; font-weight: 700; color: var(--navy); margin-bottom: 12px; }
.eyebrow::before { content: ""; width: 24px; height: 3px; border-radius: 2px; background: var(--sky); }
.eyebrow-inv { color: var(--sky-light); }
.eyebrow-inv::before { background: var(--yellow); }
.link { display: inline-flex; align-items: center; gap: 4px; font-weight: 700; color: var(--navy); text-decoration: underline; text-decoration-color: var(--sky); text-decoration-thickness: 2px; text-underline-offset: 5px; white-space: nowrap; }
.link:hover { text-decoration-color: var(--navy); }
.link-btn { display: inline-flex; align-items: center; gap: 6px; font-size: 14px; font-weight: 600; color: var(--navy); text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--control); min-height: 32px; }
.link-btn:hover { text-decoration-color: var(--navy); }
.link-strong { font-size: 16px; font-weight: 700; text-decoration-color: var(--sky); text-decoration-thickness: 2px; }
.inline-link { text-decoration: underline; font-weight: 600; }

/* ---------- Icons ---------- */
.ic { width: 20px; height: 20px; flex: none; }
.ic-sm { width: 16px; height: 16px; }
.ic-lg { width: 28px; height: 28px; }
.ic-xl { width: 40px; height: 40px; }

/* ---------- Buttons ---------- */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: var(--btn); padding: 0 20px; border-radius: var(--r-md); border: 1.5px solid transparent; font-size: 16px; font-weight: 700; line-height: 1; white-space: nowrap; cursor: pointer; transition: background-color .15s, border-color .15s, color .15s; }
.btn .ic { width: 18px; height: 18px; }
.btn-primary { background: var(--yellow); color: var(--navy); }
.btn-primary:hover { background: var(--yellow-hover); }
.btn-primary:active { background: #f2c200; }
.btn-outline { background: var(--white); color: var(--navy); border-color: var(--sky-light); }
.btn-outline:hover { border-color: var(--navy); background: var(--page); }
.btn-navy { background: var(--navy); color: #fff; }
.btn-navy:hover { background: var(--navy-2); }
.btn-lg { height: var(--btn-lg); padding: 0 24px; }
.btn-block { width: 100%; }
.btn[disabled] { opacity: .5; cursor: not-allowed; }
.btn-row { display: flex; flex-wrap: wrap; align-items: center; gap: 12px 20px; }
.btn-row-center { justify-content: center; }
.icon-btn { display: inline-grid; place-items: center; width: 40px; height: 40px; border-radius: var(--r-md); color: var(--navy); flex: none; transition: background-color .15s; }
.icon-btn:hover { background: var(--page); }
.btn-cart { display: inline-grid; place-items: center; width: 44px; height: 36px; border-radius: var(--r-sm); background: var(--yellow); color: var(--navy); flex: none; position: relative; z-index: 2; transition: background-color .15s; }
.btn-cart:hover { background: var(--yellow-hover); }
.btn-cart.is-added { background: var(--navy); color: #fff; }

/* ---------- Badges & chips ---------- */
.badge { display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 8px; border-radius: var(--r-sm); font-size: 12px; font-weight: 700; line-height: 1; white-space: nowrap; }
.badge-yellow { background: var(--yellow); color: var(--navy); }
.badge-sky { background: var(--sky); color: var(--navy); }
.badge-navy { background: var(--navy); color: #fff; }
.badge-soft { background: var(--panel); color: var(--navy); }
.badge-line { background: #fff; color: var(--navy); border: 1px solid var(--sky-light); }

